package demo.controller;

import demo.service.RefundService;
import java.math.BigDecimal;

export interface RefundRequest {
  orderId: string
  userId: string
  amount: number
}

{
  "name": "demo-repository",
  "purpose": "RepoPilot local scanner and code retrieval fixture",
  "features": ["order-refund", "wallet-balance"]
}

public OrderController(RefundService refunds) {
    this.refunds = refunds;
}

public RefundService(WalletService wallets) {
    this.wallets = wallets;
}

CREATE TABLE orders (
    id VARCHAR(64) PRIMARY KEY,
    user_id VARCHAR(64) NOT NULL,
    amount DECIMAL(12, 2) NOT NULL,
    status VARCHAR(20) NOT NULL
);

CREATE TABLE wallets (
    user_id VARCHAR(64) PRIMARY KEY,
    balance DECIMAL(12, 2) NOT NULL DEFAULT 0
);

public void credit(String userId, BigDecimal amount) {
    if (userId == null || userId.isBlank()) {
        throw new IllegalArgumentException("User ID is required");
    }
    if (amount == null || amount.signum() <= 0) {
        throw new IllegalArgumentException("Amount must be positive");
    }
    balances.merge(userId, amount, BigDecimal::add);
}

public BigDecimal balanceOf(String userId) {
    return balances.getOrDefault(userId, BigDecimal.ZERO);
}

